"""
Hypr-Hybrid-Layout Core Switcher
"""

import os
import shutil
import subprocess

TRADITIONAL_CONF = """# --- Traditional Floating Desktop Layout ---
# Generated by hypr-hybrid-layout
general {
    gaps_in = 4
    gaps_out = 8
    border_size = 2
}

decoration {
    rounding = 8
    dim_inactive = false
}

# Automatically spawn new windows floating & centered
windowrulev2 = float, class:^(.*)$
windowrulev2 = size 70% 70%, class:^(.*)$
windowrulev2 = center, class:^(.*)$
"""

TILING_CONF = """# --- Dynamic Tiling Layout ---
# Generated by hypr-hybrid-layout
general {
    gaps_in = 2
    gaps_out = 4
    border_size = 2
}

decoration {
    rounding = 0
    dim_inactive = true
}

# Standard tiling layout behavior
"""

def get_config_path() -> str:
    return os.path.expanduser("~/.config/hypr/layout.conf")

def get_state_path() -> str:
    return os.path.expanduser("~/.local/state/hypr-hybrid-layout/mode")

def get_current_mode() -> str:
    state_file = get_state_path()
    if os.path.exists(state_file):
        try:
            with open(state_file, "r") as f:
                return f.read().strip()
        except Exception:
            pass
    return "tiling"

def apply_mode(mode: str) -> bool:
    target = mode.lower().strip()
    if target not in ("tiling", "traditional", "floating"):
        raise ValueError(f"Unknown mode: {mode}. Choose 'tiling' or 'traditional'")

    is_traditional = target in ("traditional", "floating")
    content = TRADITIONAL_CONF if is_traditional else TILING_CONF
    normalized_mode = "traditional" if is_traditional else "tiling"

    conf_path = get_config_path()
    os.makedirs(os.path.dirname(conf_path), exist_ok=True)
    with open(conf_path, "w") as f:
        f.write(content)

    state_path = get_state_path()
    os.makedirs(os.path.dirname(state_path), exist_ok=True)
    with open(state_path, "w") as f:
        f.write(normalized_mode + "\n")

    # Reload Hyprland compositor if running
    if shutil.which("hyprctl"):
        subprocess.run(["hyprctl", "reload"], capture_output=True)

    # Send desktop notification
    if shutil.which("notify-send"):
        msg = "Floating Mode (8px rounding, floating windows)" if is_traditional else "Tiling Mode (0px sharp geometric tiles)"
        subprocess.run(["notify-send", "-a", "Hyprland", "Desktop Layout", f"Switched to {msg}"], capture_output=True)

    return True

def toggle_mode() -> str:
    current = get_current_mode()
    new_mode = "traditional" if current == "tiling" else "tiling"
    apply_mode(new_mode)
    return new_mode
